// src/template/template.controller.ts
import { Controller, Post, Body, Get, Query, Req } from '@nestjs/common';
import { TemplateService } from './template.service';
import { IsString, IsOptional } from 'class-validator';

export class RenderTemplateDto {
  @IsString()
  template: string;

  @IsOptional()
  @IsString()
  locale?: string;

  @IsOptional()
  context?: Record<string, any>;
}

@Controller('api/v2/templates')
export class TemplateController {
  constructor(private readonly templateService: TemplateService) {}

  @Post('render')
  async renderTemplate(@Body() dto: RenderTemplateDto, @Req() req: any) {
    const clientIp = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
    // Log for audit trail
    console.log(`[TEMPLATE_RENDER] ip=${clientIp} template_length=${dto.template.length}`);

    const result = await this.templateService.render(dto.template, dto.context || {});
    return { rendered: result, locale: dto.locale || 'en' };
  }

  @Get('preview')
  async previewTemplate(@Query('tpl') tpl: string, @Query('data') data: string) {
    const context = data ? JSON.parse(data) : {};
    const result = await this.templateService.render(tpl, context);
    return { preview: result };
  }
}

