import { Injectable } from '@nestjs/common';
import * as nunjucks from 'nunjucks';

@Injectable()
export class TemplateService {
  private env: nunjucks.Environment;

  constructor() {
    // Configure nunjucks with no filesystem access
    this.env = new nunjucks.Environment(null, {
      autoescape: false,  // Required for HTML email templates
      throwOnUndefined: false,
    });

    // Register custom filters used by marketing team
    this.env.addFilter('currency', (val: number, symbol: string = '$') => {
      return `${symbol}${val.toFixed(2)}`;
    });

    this.env.addFilter('truncate', (str: string, len: number) => {
      if (str.length <= len) return str;
      return str.substring(0, len) + '...';
    });
  }

  async render(template: string, context: Record<string, any>): Promise<string> {
    // Basic length check to prevent abuse
    if (template.length > 10000) {
      throw new Error('Template exceeds maximum length');
    }

    // Render the template string directly with user-provided context
    return new Promise((resolve, reject) => {
      try {
        const rendered = this.env.renderString(template, context);
        resolve(rendered);
      } catch (err) {
        reject(new Error(`Template rendering failed: ${err.message}`));
      }
    });
  }
}

